Review Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Review Service", "Review Service") {
    Component("Review Controller", "Review Controller", "Express.js", "Handles incoming HTTP requests related to reviews via REST and gRPC.")
    Component("Review Business Logic Component", "Review Business Logic Component", "Node.js", "Contains core business logic for processing and validating reviews.")
    Component("Data Access Layer & ElastiCache Read-Aside", "Data Access Layer & ElastiCache Read-Aside", "Prisma ORM + Redis", "Manages persistence in PostgreSQL and caches rating summaries using Redis.")
    Component("Event Publisher Component", "Event Publisher Component", "AWS SDK v3", "Publishes asynchronous events like ReviewCreated and GDPR anonymization to AWS EventBridge.")
}

Rel("Review Controller", "Review Business Logic Component", "Delegates request processing")
Rel("Review Business Logic Component", "Data Access Layer & ElastiCache Read-Aside", "Queries and persists data")
Rel("Review Business Logic Component", "Event Publisher Component", "Triggers domain events")

@enduml

AWS EventBridge.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the AWS EventBridge container

Container_Boundary(aws_eventbridge, "AWS EventBridge") {
    Component(CustomEventBuses, "Custom Event Buses", "AWS EventBridge Custom Buses", "Domain-isolated event buses preventing cascading failures for decoupled microservice communication.")
    Component(EventRules, "Event Rules", "AWS EventBridge Rules", "Internal event routing rules to match and direct events to appropriate targets.")
    Component(TargetDispatchers, "Target Dispatchers", "AWS Lambda / EventBridge Targets", "Dispatchers responsible for forwarding routed events to downstream buffers and queues.")
}

Rel(CustomEventBuses, EventRules, "Routes published events based on defined rule patterns", "")
Rel(EventRules, TargetDispatchers, "Triggers dispatchers to forward matched events", "")

@enduml
